/* GENERAT AUTOMAT de scripts/build-pages.mjs — nu edita manual. Secțiune din js/data.js. */
window.SITE_ACTIVITIES = [{"id":"traseu-pietrele-bucura-peleaga","name":"Traseu Cabana Pietrele – Lacul Bucura – Vf. Peleaga","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"hateg","coords":[45.3583,22.875],"hasReviews":false,"images":["images/traseu-peleaga.jpg"],"photoCredit":{"author":"Daniel Ighișan","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Varful_Peleaga.jpg"},"ro":{"tagline":"Clasicul traseu din Retezat: de la Cabana Pietrele (1.480 m), la Lacul Bucura și pe Vf. Peleaga (2.509 m).","description":["Traseul pornește de la Cabana Pietrele și urcă spre Lacul Bucura, cel mai mare lac glaciar din România — de aici, ultimul tronson spre Vf. Peleaga durează în jur de 2–2,5 ore și are porțiuni de grohotiș instabil.","E un traseu de o zi, solicitant, potrivit doar cu echipament de munte; ultimul tronson (Bucura–Peleaga) se închide iarna din cauza riscului de avalanșă."],"facts":[{"label":"Punct de plecare","value":"Cabana Pietrele (1.480 m)"},{"label":"Dificultate","value":"Medie–dificilă, porțiuni de grohotiș"},{"label":"Sezon","value":"Tronsonul Bucura–Peleaga se închide iarna (risc de avalanșă)"}]},"en":{"name":"Pietrele Hut – Lake Bucura – Peleaga Peak trail","tagline":"The classic Retezat route: from Pietrele Hut (1,480 m), to Lake Bucura and Peleaga Peak (2,509 m).","description":["The trail starts at Pietrele Hut and climbs to Lake Bucura, Romania's largest glacial lake — from there, the last stretch to Peleaga Peak takes around 2–2.5 hours and has sections of unstable scree.","It's a demanding day hike, suitable only with proper mountain gear; the last stretch (Bucura–Peleaga) closes in winter due to avalanche risk."],"facts":[{"label":"Starting point","value":"Pietrele Hut (1,480 m)"},{"label":"Difficulty","value":"Medium–hard, scree sections"},{"label":"Season","value":"The Bucura–Peleaga stretch closes in winter (avalanche risk)"}]}},{"id":"partiile-parang","name":"Pârtiile de schi din Parâng","category":{"ro":"Schi","en":"Skiing"},"area":"Parâng","hasReviews":false,"season":"iarna","images":["images/partii-parang.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_C%C3%A2lcescu_-_panoramio.jpg"},"ro":{"tagline":"Domeniu schiabil la cca. 15 km de Petroșani, cu telescaun de la 950 la 1.650 m.","description":["Stațiunea Parâng are 9 pârtii însumând circa 8 km, deservite de 9 instalații de transport pe cablu. Telescaunul urcă din zona Petroșani până la 1.650 m altitudine, pe un traseu de 700 m diferență de nivel."],"facts":[{"label":"Acces","value":"cca. 15 km de Petroșani"},{"label":"Telescaun","value":"de la 950 m la 1.650 m altitudine"},{"label":"Domeniu","value":"cca. 8 km, 9 pârtii, 9 instalații"}]},"en":{"name":"Parâng ski slopes","tagline":"A ski area about 15 km from Petroșani, with a chairlift climbing from 950 to 1,650 m.","description":["The Parâng resort has 9 slopes totalling about 8 km, served by 9 cable lifts. The chairlift climbs from the Petroșani area up to 1,650 m altitude, a 700 m difference in elevation."],"facts":[{"label":"Access","value":"approx. 15 km from Petroșani"},{"label":"Chairlift","value":"from 950 m to 1,650 m altitude"},{"label":"Ski area","value":"approx. 8 km, 9 slopes, 9 lifts"}]}},{"id":"statiunea-straja","name":"Stațiunea de schi Straja","category":{"ro":"Schi","en":"Skiing"},"area":"Vâlcan","townId":"lupeni","coords":[45.3207,23.2369],"hasReviews":false,"season":"iarna","images":["images/statiunea-straja.jpg"],"photoCredit":{"author":"Albundy64","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Ski_resort_Straja.jpg"},"ro":{"tagline":"Declarată stațiune în 2002, cu cel mai întins domeniu schiabil din județ — cca. 26 km de pârtii.","description":["Straja se află la 1.440 m altitudine, în Munții Vâlcan, accesibilă din Lupeni pe un drum asfaltat de 8 km sau cu telegondola. Domeniul schiabil are circa 26 km (din care 20 km cu zăpadă artificială), 12 pârtii și 11 instalații de transport pe cablu, între 1.130 și 1.868 m altitudine (Vf. Straja).","Cea mai lungă pârtie, Straja Strand, are 3,8 km."],"facts":[{"label":"Altitudine","value":"1.130–1.868 m (Vf. Straja)"},{"label":"Acces","value":"din Lupeni — 8 km drum asfaltat sau telegondolă"},{"label":"Domeniu","value":"cca. 26 km (20 km cu zăpadă artificială), 12 pârtii, 11 instalații"}]},"en":{"name":"Straja ski resort","tagline":"Declared a resort in 2002, with the county's largest ski area — about 26 km of slopes.","description":["Straja sits at 1,440 m altitude, in the Vâlcan Mountains, reachable from Lupeni via an 8 km paved road or by gondola. The ski area covers about 26 km (20 km with artificial snow), 12 slopes and 11 cable lifts, between 1,130 and 1,868 m altitude (Straja Peak).","The longest slope, Straja Strand, is 3.8 km."],"facts":[{"label":"Altitude","value":"1,130–1,868 m (Straja Peak)"},{"label":"Access","value":"from Lupeni — 8 km paved road or gondola"},{"label":"Ski area","value":"approx. 26 km (20 km artificial snow), 12 slopes, 11 lifts"}]}},{"id":"sania-straja","name":"Sania pe șine Straja (Baloo Coaster)","category":{"ro":"Sanie pe șine","en":"Alpine coaster"},"area":"Vâlcan","townId":"lupeni","hasReviews":true,"season":"tot-anul","images":["images/sania-straja.jpg"],"photoCredit":{"author":"Ski Straja","license":"material promoțional al afacerii","source":"https://skistraja.ro/baloo-coaster/","sourceLabel":"skistraja.ro"},"ro":{"tagline":"Prima sanie pe șine din Hunedoara, o coborâre cu adrenalină prin pădurea de la Straja.","description":["Sania pe șine (Baloo Coaster) este o atracție de tip alpine coaster deschisă la finalul anului 2025 în stațiunea Straja, lângă Lupeni, la poalele Munților Vâlcan. Instalația a fost realizată printr-o investiție de aproximativ 2,6 milioane de euro, finanțată prin Programul pentru Tranziție Justă.","Traseul, lung de circa 1,4 km, traversează pârtia Sfântul Gheorghe prin două poduri suspendate și include patru spirale care mențin adrenalina la cote înalte. Sania are două locuri, se deplasează pe șine duble pentru siguranță sporită și poate atinge o viteză maximă de aproximativ 40 km/h."],"facts":[{"label":"Lungime traseu","value":"~1,4 km"},{"label":"Viteză maximă","value":"~40 km/h"},{"label":"Investiție","value":"~2,6 milioane euro (fonduri Tranziție Justă)"}]},"en":{"name":"Straja alpine coaster (Baloo Coaster)","tagline":"Hunedoara's first alpine coaster — an adrenaline ride through the forest at Straja.","description":["The Baloo Coaster alpine coaster opened in late 2025 at the Straja resort, near Lupeni, at the foot of the Vâlcan Mountains. The installation was built through an investment of about €2.6 million, funded through the Just Transition Program.","The roughly 1.4 km track crosses the Sfântul Gheorghe ski slope over two suspended bridges and includes four spirals for extra thrills. The two-seat sled runs on a double rail system for added safety and can reach a top speed of about 40 km/h."],"facts":[{"label":"Track length","value":"~1.4 km"},{"label":"Top speed","value":"~40 km/h"},{"label":"Investment","value":"~€2.6 million (Just Transition funding)"}]}},{"id":"traseu-dealul-babii","name":"Traseul Dealul Babii","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Petroșani","townId":"petrosani","hasReviews":true,"season":"primavara","images":["images/placeholder.svg"],"ro":{"tagline":"Culme domoală între Vulcan și Merișor, vestită primăvara pentru covorul de ghiocei.","description":["Dealul Babii este o zonă deluroasă situată între orașul Vulcan și satul Merișor, parte a unui traseu de drumeție care pleacă din Petroșani, trece prin Aninoasa, Vulcan, Dealu Babii, Pasul Dealu Babii, Merișor și Bănița, revenind în buclă spre Petroșani — un circuit de aproximativ 44 km, cu altitudini între cca. 550 m și puțin peste 900 m.","Zona este cunoscută mai ales primăvara, când ghioceii înfloresc pe o porțiune de aproximativ 3 km de deal, transformând Dealul Babii într-un „covor alb”, un obiectiv apreciat de localnici și drumeți din Valea Jiului."],"facts":[{"label":"Lungime circuit","value":"~44 km (Petroșani–Vulcan–Dealu Babii–Merișor–Bănița–Petroșani)"},{"label":"Altitudine","value":"~550–900 m"},{"label":"Perioadă recomandată","value":"primăvara, pentru înflorirea ghioceilor"}]},"en":{"name":"Dealul Babii trail","tagline":"A gentle ridge between Vulcan and Merișor, famous in spring for its carpet of snowdrops.","description":["Dealul Babii is a hilly area between the town of Vulcan and the village of Merișor, part of a hiking loop that starts in Petroșani, passes through Aninoasa, Vulcan, Dealu Babii, Dealu Babii Pass, Merișor and Bănița, and loops back to Petroșani — a circuit of about 44 km, climbing from roughly 550 m to just over 900 m.","The area is best known in spring, when snowdrops bloom across about 3 km of hillside, turning Dealul Babii into a white carpet — a favourite spot for locals and hikers in the Jiu Valley."],"facts":[{"label":"Loop length","value":"~44 km (Petroșani–Vulcan–Dealu Babii–Merișor–Bănița–Petroșani)"},{"label":"Elevation","value":"~550–900 m"},{"label":"Best season","value":"spring, for the snowdrop bloom"}]}},{"id":"bazin-inot-petrosani","name":"Bazinul Didactic de Înot „Avram Iancu” Petroșani","category":{"ro":"Bazin de înot didactic","en":"Educational swimming pool"},"area":"Petroșani","townId":"petrosani","hasReviews":true,"season":"tot-anul","images":["images/bazin-inot-petrosani.jpg"],"photoCredit":{"author":"Bazin Înot Didactic „Iancu Avram” Petroșani","license":"material de promovare al instituției","source":"https://www.facebook.com/BazinInotDidacticIancuAvramPetrosani","sourceLabel":"Facebook"},"ro":{"tagline":"Bazin semiolimpic acoperit, redeschis în 2025 după modernizare, în cartierul Aeroport.","description":["Bazinul Didactic de Înot „Avram Iancu” din Petroșani este un bazin semiolimpic de 12,5 × 25 m, cu adâncime variabilă între 1,20 și 1,80 m, situat pe strada Oituz, în cartierul Aeroport. Facilitatea include saună, vestiare și o masă de tenis, fiind folosită atât pentru cursuri de înot pentru elevi, cât și pentru înot liber.","După lucrări de modernizare (centrală termică, acoperiș, ventilație), bazinul s-a redeschis publicului pe 20 octombrie 2025."],"facts":[{"label":"Dimensiuni","value":"12,5 × 25 m, adâncime 1,20–1,80 m"},{"label":"Program","value":"Luni–Vineri, 09:00–21:00"},{"label":"Adresă","value":"Str. Oituz, cartier Aeroport, Petroșani"}]},"en":{"name":"\"Avram Iancu\" Educational Swimming Pool, Petroșani","tagline":"A covered semi-Olympic pool, reopened in 2025 after modernisation, in the Aeroport district.","description":["The \"Avram Iancu\" Educational Swimming Pool in Petroșani is a semi-Olympic pool measuring 12.5 × 25 m, with variable depth between 1.20 and 1.80 m, located on Oituz Street, in the Aeroport district. The facility includes a sauna, changing rooms and a table-tennis table, used both for swimming lessons for pupils and for open swimming.","After modernisation works (heating plant, roof, ventilation), the pool reopened to the public on 20 October 2025."],"facts":[{"label":"Dimensions","value":"12.5 × 25 m, 1.20–1.80 m depth"},{"label":"Hours","value":"Monday–Friday, 09:00–21:00"},{"label":"Address","value":"Oituz Street, Aeroport district, Petroșani"}]}},{"id":"bazin-inot-petrila","name":"Bazinul de Înot Didactic Petrila","category":{"ro":"Bazin de înot didactic","en":"Educational swimming pool"},"area":"Petrila","townId":"petrila","hasReviews":true,"season":"tot-anul","images":["images/bazin-inot-petrila.jpg"],"photoCredit":{"author":"Loraine","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Petrila_view.jpg"},"ro":{"tagline":"Bazin didactic de 25×12,5 m, cu 5 culoare, lângă Școala nr. 5.","description":["Bazinul de înot de la Petrila, deschis publicului din ianuarie 2022, are 25 × 12,5 m, adâncime variabilă între 1,20 și 1,80 m și 5 culoare de înot, cu blocuri de start la capătul mai adânc — folosit atât pentru cursuri școlare, cât și pentru acces public.","Este situat pe strada 8 Martie, lângă Școala Gimnazială nr. 5. Bazinul e închis lunea pentru curățenie și dezinfecție."],"facts":[{"label":"Program","value":"Marți–Sâmbătă 09:00–21:00 (ultima intrare 19:00), Duminică 12:00–20:00 (ultima intrare 18:00), închis lunea"},{"label":"Tarife","value":"16 lei adulți / 8 lei elevi-studenți, ședință de 2 ore"},{"label":"Adresă","value":"Str. 8 Martie, lângă Școala nr. 5, Petrila"}]},"en":{"name":"Educational Swimming Pool, Petrila","tagline":"A 25×12.5 m educational pool with 5 lanes, next to School No. 5.","description":["The swimming pool in Petrila, open to the public since January 2022, measures 25 × 12.5 m, with variable depth between 1.20 and 1.80 m and 5 swimming lanes, with starting blocks at the deeper end — used both for school lessons and public access.","It's located on 8 Martie Street, next to School No. 5. The pool is closed on Mondays for cleaning and disinfection."],"facts":[{"label":"Hours","value":"Tuesday–Saturday 09:00–21:00 (last entry 19:00), Sunday 12:00–20:00 (last entry 18:00), closed Mondays"},{"label":"Prices","value":"16 lei adults / 8 lei pupils-students, 2-hour session"},{"label":"Address","value":"8 Martie Street, next to School No. 5, Petrila"}]}},{"id":"bazin-inot-vulcan","name":"Bazinul Didactic de Înot Vulcan","category":{"ro":"Bazin de înot didactic","en":"Educational swimming pool"},"area":"Vulcan","townId":"vulcan","hasReviews":true,"season":"tot-anul","images":["images/bazin-inot-vulcan.jpg"],"photoCredit":{"author":"Bazin de Înot Didactic Vulcan","license":"material de promovare al instituției","source":"https://www.facebook.com/profile.php?id=100085120656982","sourceLabel":"Facebook"},"ro":{"tagline":"Bazin semiolimpic în centrul orașului, între Minimax și biserica de lângă Primărie.","description":["Bazinul Didactic de Înot din Vulcan, dat în folosință în 2022, este un bazin semiolimpic de 25 × 12,5 m, cu adâncime între 1,20 și 1,80 m și apă încălzită la 24,6–26°C. E dedicat în primul rând elevilor din municipiu, care fac aici cursuri de înot, dar are program și pentru publicul larg.","Se află pe strada Platoului, între magazinul Minimax și biserica de lângă Primărie."],"facts":[{"label":"Program","value":"Luni–Vineri 09:00–21:00, Sâmbătă–Duminică 09:00–17:00"},{"label":"Temperatura apei","value":"24,6–26°C"},{"label":"Adresă","value":"Str. Platoului, Vulcan"}]},"en":{"name":"Educational Swimming Pool, Vulcan","tagline":"A semi-Olympic pool in the town centre, between the Minimax store and the church by the town hall.","description":["The Educational Swimming Pool in Vulcan, opened in 2022, is a semi-Olympic pool measuring 25 × 12.5 m, with depth between 1.20 and 1.80 m and water heated to 24.6–26°C. It's primarily meant for the town's pupils, who take swimming lessons there, but it's also open to the general public.","It's located on Platoului Street, between the Minimax store and the church next to the town hall."],"facts":[{"label":"Hours","value":"Monday–Friday 09:00–21:00, Saturday–Sunday 09:00–17:00"},{"label":"Water temperature","value":"24.6–26°C"},{"label":"Address","value":"Platoului Street, Vulcan"}]}},{"id":"bazin-inot-lupeni","name":"Bazinul Didactic de Înot Lupeni","category":{"ro":"Bazin de înot didactic","en":"Educational swimming pool"},"area":"Lupeni","townId":"lupeni","hasReviews":true,"season":"tot-anul","images":["images/bazin-inot-lupeni.jpg"],"photoCredit":{"author":"Bazinul de Înot Didactic Lupeni","license":"material de promovare al instituției","source":"https://www.facebook.com/profile.php?id=61585943950211","sourceLabel":"Facebook"},"ro":{"tagline":"Cel mai nou bazin didactic din Valea Jiului, inaugurat în decembrie 2025 la poalele Străjii.","description":["Bazinul didactic de înot din Lupeni, al patrulea de acest tip din Valea Jiului, a fost inaugurat pe 5 decembrie 2025, după o investiție de peste 12 milioane de lei și circa trei ani de lucrări. Se află la poalele stațiunii Straja, deservind atât localnicii, cât și turiștii cazați la munte.","Pe lângă înot liber și cursuri, bazinul oferă saună și pachete combinate înot+saună."],"facts":[{"label":"Program","value":"Luni–Joi 10:00–21:00, Vineri–Duminică 12:00–22:00"},{"label":"Tarife","value":"20 lei adulți / 10 lei preșcolari-elevi, ședință de max. 90 min"},{"label":"Deschis","value":"5 decembrie 2025"}]},"en":{"name":"Educational Swimming Pool, Lupeni","tagline":"The newest educational pool in the Jiu Valley, opened in December 2025 at the foot of Straja.","description":["The educational swimming pool in Lupeni, the fourth of its kind in the Jiu Valley, opened on 5 December 2025, after an investment of over 12 million lei and about three years of works. It sits at the foot of the Straja resort, serving both locals and tourists staying in the mountains.","Besides open swimming and lessons, the pool offers a sauna and combined swim+sauna packages."],"facts":[{"label":"Hours","value":"Monday–Thursday 10:00–21:00, Friday–Sunday 12:00–22:00"},{"label":"Prices","value":"20 lei adults / 10 lei preschoolers-pupils, session up to 90 min"},{"label":"Opened","value":"5 December 2025"}]}},{"id":"traseul-tunelelor-vulcan","name":"Traseul Tunelelor","category":{"ro":"Traseu tematic","en":"Themed trail"},"area":"Vulcan","townId":"vulcan","hasReviews":true,"season":"tot-anul","images":["images/cascada-dracului-vulcan.jpg"],"photoCredit":{"author":"Bogdan Muraru","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cascada_Vulcan.jpg"},"ro":{"tagline":"Traseu tematic ușor-mediu prin munții de lângă Vulcan, cu Peștera și Cascada Dracului.","description":["Traseul Tunelelor este unul dintre cele cinci poteci turistice tematice amenajate în 2022 în zona montană a municipiului Vulcan, dintr-o inițiativă a Grupului Pro Montana, realizată de Primăria Vulcan cu sprijinul Salvamont Hunedoara.","Lung de aproximativ 6 km (3–4 ore dus-întors), de dificultate ușoară spre medie, traseul trece pe lângă foste construcții hidrotehnice abandonate și duce la Peștera Dracului, Cascada Dracului și izvoarele Baleii — poate fi parcurs pe jos, cu bicicleta sau, iarna, cu schiurile."],"facts":[{"label":"Lungime","value":"~6 km (3–4 ore dus-întors)"},{"label":"Dificultate","value":"ușoară-medie"},{"label":"Obiective pe traseu","value":"Peștera Dracului, Cascada Dracului, Izvoarele Baleii"},{"label":"Amenajat","value":"2022, Pro Montana + Primăria Vulcan + Salvamont Hunedoara"}]},"en":{"name":"Tunnels Trail","tagline":"An easy-to-moderate themed trail near Vulcan, leading to the Devil's Cave and Waterfall.","description":["Traseul Tunelelor (\"the tunnels trail\") is one of five themed hiking trails set up in 2022 in the mountains near Vulcan, an initiative of the Pro Montana group, carried out by Vulcan Town Hall with support from Salvamont Hunedoara.","About 6 km long (3–4 hours round trip), easy to moderate in difficulty, the trail passes abandoned hydro-technical structures and leads to the Devil's Cave (Peștera Dracului), the Devil's Waterfall (Cascada Dracului) and the Baleia springs — it can be covered on foot, by bike or, in winter, on skis."],"facts":[{"label":"Length","value":"~6 km (3–4 hours round trip)"},{"label":"Difficulty","value":"easy-moderate"},{"label":"Landmarks","value":"Devil's Cave, Devil's Waterfall, Baleia springs"},{"label":"Built","value":"2022, Pro Montana + Vulcan Town Hall + Salvamont Hunedoara"}]}},{"id":"traseul-ruinelor-aninoasa","name":"Traseul Ruinelor","category":{"ro":"Traseu tematic","en":"Themed trail"},"area":"Aninoasa","townId":"aninoasa","hasReviews":true,"season":"tot-anul","images":["images/traseul-ruinelor-aninoasa.jpg"],"photoCredit":{"author":"Organizația de Management al Destinației Valea Jiului","license":"material de promovare al instituției","source":"https://www.facebook.com/profile.php?id=61579481461946","sourceLabel":"Facebook"},"ro":{"tagline":"Traseu de 12 km de la Vulcan la Aninoasa, pe Valea Ungurului, cu mănăstire, cascadă și ruine.","description":["Traseul Ruinelor este cel mai lung dintre cele cinci poteci tematice amenajate în 2022 lângă Vulcan (proiect Pro Montana, Primăria Vulcan și Salvamont Hunedoara). Pornește din Vulcan și urmează cursul Văii Ungurului până în Aninoasa, pe o distanță de aproximativ 12 km, de dificultate medie.","Pe parcurs se află Mănăstirea Sf. Nicolae, Cascada Ungurului, formațiunea stâncoasă numită Sfinxul Văii Ungurului și mai multe ruine istorice de construcții din piatră — de unde și numele traseului."],"facts":[{"label":"Traseu","value":"Vulcan → Valea Ungurului → Aninoasa, ~12 km"},{"label":"Dificultate","value":"medie"},{"label":"Obiective pe traseu","value":"Mănăstirea Sf. Nicolae, Cascada Ungurului, Sfinxul Văii Ungurului, ruine"},{"label":"Amenajat","value":"2022, Pro Montana + Primăria Vulcan + Salvamont Hunedoara"}]},"en":{"name":"Ruins Trail","tagline":"A 12 km trail from Vulcan to Aninoasa along Valea Ungurului, with a monastery, waterfall and ruins.","description":["Traseul Ruinelor (\"the ruins trail\") is the longest of five themed trails set up in 2022 near Vulcan (a Pro Montana project, with Vulcan Town Hall and Salvamont Hunedoara). It starts in Vulcan and follows the Valea Ungurului stream to Aninoasa, covering about 12 km at moderate difficulty.","Along the way lie Sf. Nicolae Monastery, Cascada Ungurului waterfall, a rock formation known as the Sphinx of Valea Ungurului, and several historic stone ruins — which give the trail its name."],"facts":[{"label":"Route","value":"Vulcan → Valea Ungurului → Aninoasa, ~12 km"},{"label":"Difficulty","value":"moderate"},{"label":"Landmarks","value":"Sf. Nicolae Monastery, Cascada Ungurului waterfall, the Valea Ungurului Sphinx, ruins"},{"label":"Built","value":"2022, Pro Montana + Vulcan Town Hall + Salvamont Hunedoara"}]}},{"id":"parcul-cetatii-deva","name":"Parcul Cetății Deva","category":{"ro":"Parc & acces cetate","en":"Park & citadel access"},"area":"Deva","townId":"deva","hasReviews":true,"season":"tot-anul","images":["images/parcul-cetatii-deva.jpg"],"photoCredit":{"author":"Carmen buzan","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Parcul_Cetatii_Deva.JPG"},"ro":{"tagline":"Parcul de la poalele Cetății Deva — punctul de plecare pentru potecile pietonale, minibuzul electric și telecabina (oprită momentan) spre platoul cetății.","description":["Parcul Cetății se întinde la baza dealului vulcanic pe care se află Cetatea Deva și este punctul de plecare pentru mai multe poteci pietonale marcate spre platoul cetății, un urcuș de aproximativ 40 de minute, de dificultate medie, pe pietriș și trepte.","Telecabina (prima instalație din 2003, modernizată și reinaugurată în martie 2024) are un traseu de 278 m lungime, o diferență de nivel de 158 m și cabine de 30 de locuri. Din noiembrie 2025 este oprită din cauza unor defecțiuni tehnice, iar repornirea depinde de avizul unor experți străini (estimare: primăvara lui 2027). Până atunci, la cetate se ajunge pe jos sau cu minibuzul electric de 22 de locuri, de regulă zilnic între 09:00 și 18:00, cu variații sezoniere. Parcarea la baza dealului este gratuită."],"facts":[{"label":"Poteci pietonale","value":"~40 min, dificultate medie"},{"label":"Telecabină","value":"OPRITĂ din noiembrie 2025; 278 m lungime, diferență de nivel 158 m, cabine de 30 locuri"},{"label":"Minibuz electric","value":"22 locuri, de regulă 09:00–18:00"},{"label":"Parcare","value":"gratuită, la baza dealului"}]},"en":{"name":"Citadel Park, Deva","tagline":"The park at the foot of Deva Citadel — the starting point for the walking trails, the electric minibus and the cable car (currently out of service) up to the citadel plateau.","description":["Parcul Cetății spreads at the base of the volcanic hill that Deva Citadel sits on, and is the starting point for several marked walking trails up to the citadel plateau, a climb of about 40 minutes, moderate difficulty, on gravel paths and steps.","The cable car (first built in 2003, modernised and reopened in March 2024) covers a 278 m route with a 158 m height difference, in 30-person cabins. It has been out of service since November 2025 because of technical faults, and restarting it depends on the approval of foreign experts (estimate: spring 2027). Until then, visitors walk up or take the 22-seat electric minibus, which operates generally daily between 09:00 and 18:00, with seasonal variations. Parking at the base of the hill is free."],"facts":[{"label":"Walking trails","value":"~40 min, moderate difficulty"},{"label":"Cable car","value":"OUT OF SERVICE since November 2025; 278 m route, 158 m height difference, 30-seat cabins"},{"label":"Electric minibus","value":"22 seats, generally 09:00–18:00"},{"label":"Parking","value":"free, at the base of the hill"}]}},{"id":"traseu-pui-rausor","name":"Traseul Pui – Baza Salvamont Râușor","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"pui","hasReviews":false,"images":["images/traseu-pui-rausor.jpg"],"photoCredit":{"author":"Domeniul Schiabil Râușor - Retezat","license":"material promoțional al afacerii","source":"https://www.facebook.com/Domeniul.Schiabil.Rausor","sourceLabel":"Facebook"},"ro":{"tagline":"Traseu lung de acces dinspre Pui spre baza Salvamont Râușor, la poalele nordice ale Retezatului.","description":["Traseul, marcat cu bandă roșie, leagă satul Pui de baza Salvamont Râușor, punct de plecare pentru mai multe trasee spre creasta principală a Retezatului.","Cu o durată de 15–16 ore, e parcurs de regulă în etape, nu într-o singură zi."],"facts":[{"label":"Punct de plecare","value":"Pui"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"15–16 ore"}]},"en":{"name":"Pui – Râușor Salvamont Base trail","tagline":"Long access route from Pui to the Râușor Salvamont base, on the northern edge of the Retezat massif.","description":["Marked with a red band, the trail connects the village of Pui to the Râușor Salvamont base, a starting point for several routes toward the main Retezat ridge.","At 15–16 hours, it is usually covered in stages rather than in a single day."],"facts":[{"label":"Starting point","value":"Pui"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"15–16 hours"}]}},{"id":"traseu-pietrele-varful-mare","name":"Traseul Cabana Pietrele – Vârful Mare (Retezat)","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"hateg","hasReviews":false,"images":["images/traseu-varful-mare.jpg"],"photoCredit":{"author":"Harabagiu Dan (Hardsr)","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Vf-mare1.jpg"},"ro":{"tagline":"Urcare de o zi de la Cabana Pietrele la Vârful Mare, unul dintre vârfurile secundare importante ale masivului.","description":["Marcat cu triunghi roșu (cu tronsoane pe punct roșu), traseul pornește de la Cabana Pietrele (1.480 m) și urcă în circa 4 ore spre Vârful Mare.","Face parte din rețeaua de trasee care converg spre Cabana Pietrele, cel mai folosit punct de acces în partea nordică a Parcului Național Retezat."],"facts":[{"label":"Punct de plecare","value":"Cabana Pietrele (1.480 m)"},{"label":"Marcaj","value":"Triunghi roșu / punct roșu"},{"label":"Durată","value":"cca. 4 ore"}]},"en":{"name":"Pietrele Hut – Vârful Mare trail (Retezat)","tagline":"A day climb from Pietrele Hut to Vârful Mare, one of the massif's important secondary peaks.","description":["Marked with a red triangle (with red-dot sections), the trail starts at Pietrele Hut (1,480 m) and climbs for about 4 hours to Vârful Mare.","It's part of the network of trails converging on Pietrele Hut, the busiest access point in the northern part of Retezat National Park."],"facts":[{"label":"Starting point","value":"Pietrele Hut (1,480 m)"},{"label":"Marking","value":"Red triangle / red dot"},{"label":"Duration","value":"about 4 hours"}]}},{"id":"traseu-pietrele-saua-pelegii","name":"Traseul Cabana Pietrele – Șaua Pelegii","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"hateg","hasReviews":false,"images":["images/traseu-saua-pelegii.jpg"],"photoCredit":{"author":"Horia Varlan","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Bucura_and_Ana.jpg"},"ro":{"tagline":"Traseu de creastă de la Cabana Pietrele la Șaua Pelegii, punct de legătură spre mai multe văi ale Retezatului.","description":["Marcat cu triunghi galben, traseul urcă de la Cabana Pietrele (1.480 m) la Șaua Pelegii în circa 3 ore.","Șaua Pelegii e un nod important de trasee, unde se întâlnesc rutele dinspre Lacul Galeș și dinspre Baleia."],"facts":[{"label":"Punct de plecare","value":"Cabana Pietrele (1.480 m)"},{"label":"Marcaj","value":"Triunghi galben"},{"label":"Durată","value":"cca. 3 ore"}]},"en":{"name":"Pietrele Hut – Peleaga Saddle trail","tagline":"A ridge route from Pietrele Hut to Peleaga Saddle, a junction point for several Retezat valleys.","description":["Marked with a yellow triangle, the trail climbs from Pietrele Hut (1,480 m) to Peleaga Saddle in about 3 hours.","Peleaga Saddle is a major trail junction, where routes from Lake Galeș and from Baleia meet."],"facts":[{"label":"Starting point","value":"Pietrele Hut (1,480 m)"},{"label":"Marking","value":"Yellow triangle"},{"label":"Duration","value":"about 3 hours"}]}},{"id":"traseu-lacul-gales-saua-pelegii","name":"Traseul Lacul Galeș – Șaua Pelegii","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"hateg","hasReviews":false,"images":["images/traseu-lacul-gales.jpg"],"photoCredit":{"author":"Olario~commonswiki","license":"domeniu public","source":"https://commons.wikimedia.org/wiki/File:LaculGalesusiVarfulRetezatvazutedepeVarfulMare.JPG"},"ro":{"tagline":"Legătură scurtă dinspre valea Râușorului (Lacul Galeș) spre Șaua Pelegii, în versantul nordic al Retezatului.","description":["Marcat cu cruce roșie, traseul leagă Lacul Galeș, în valea Râușorului, de Șaua Pelegii, în circa 2 ore.","E un traseu scurt, folosit mai ales ca variantă de acces dinspre Baza Salvamont Râușor."],"facts":[{"label":"Punct de plecare","value":"Lacul Galeș (valea Râușorului)"},{"label":"Marcaj","value":"Cruce roșie"},{"label":"Durată","value":"cca. 2 ore"}]},"en":{"name":"Lake Galeș – Peleaga Saddle trail","tagline":"A short link from the Râușor valley (Lake Galeș) to Peleaga Saddle, on the northern slope of Retezat.","description":["Marked with a red cross, the trail connects Lake Galeș, in the Râușor valley, to Peleaga Saddle, in about 2 hours.","It's a short route, mostly used as an access variant from the Râușor Salvamont base."],"facts":[{"label":"Starting point","value":"Lake Galeș (Râușor valley)"},{"label":"Marking","value":"Red cross"},{"label":"Duration","value":"about 2 hours"}]}},{"id":"traseu-cetatea-colt","name":"Traseul Valea Nucșoara – Cetatea Colț","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Râu de Mori","townId":"rau-de-mori","hasReviews":true,"images":["images/cetatea-colt.jpg"],"photoCredit":{"author":"Razvan Socol","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Col%C8%9B.JPG"},"ro":{"tagline":"Cel mai scurt și accesibil traseu marcat la marginea Retezatului: o oră până la ruinele Cetății Colț.","description":["Marcat cu triunghi albastru, traseul urcă din valea Nucșoara până la Cetatea Colț, ruinele unei cetăți medievale ridicate de familia nobiliară română Cândea în secolul al XIV-lea, pe o stâncă ce domină satul Suseni.","Cu doar o oră de mers, e unul dintre puținele trasee din zona Retezatului potrivit și pentru familii cu copii."],"facts":[{"label":"Punct de plecare","value":"Valea Nucșoara"},{"label":"Marcaj","value":"Triunghi albastru"},{"label":"Durată","value":"cca. 1 oră"}]},"en":{"name":"Nucșoara Valley – Colț Fortress trail","tagline":"The shortest, most accessible marked trail at the edge of Retezat: an hour up to the Colț Citadel ruins.","description":["Marked with a blue triangle, the trail climbs from the Nucșoara valley to Colț Fortress, the ruins of a medieval fortress built by the Romanian noble Cândea family in the 14th century, on a rock overlooking the village of Suseni.","At only an hour long, it's one of the few trails around Retezat also suitable for families with children."],"facts":[{"label":"Starting point","value":"Nucșoara valley"},{"label":"Marking","value":"Blue triangle"},{"label":"Duration","value":"about 1 hour"}]}},{"id":"traseu-rau-de-mori-varful-retezat","name":"Traseul Râu de Mori – Vârful Retezat","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"rau-de-mori","hasReviews":false,"images":["images/traseu-varful-retezat.jpg"],"photoCredit":{"author":"Dezidor","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:V%C3%A2rful_Retezat.jpg"},"ro":{"tagline":"Ascensiune lungă dinspre sud, din satul Râu de Mori, direct spre Vârful Retezat.","description":["Marcat cu triunghi roșu, traseul urcă din Râu de Mori spre Vârful Retezat în 7–8 ore, pe versantul sudic al masivului, mai puțin umblat decât rutele dinspre Cabana Pietrele.","E o variantă solicitantă pentru cei care vor să evite aglomerația din nordul parcului."],"facts":[{"label":"Punct de plecare","value":"Râu de Mori"},{"label":"Marcaj","value":"Triunghi roșu"},{"label":"Durată","value":"7–8 ore"}]},"en":{"name":"Râu de Mori – Retezat Peak trail","tagline":"A long ascent from the south, starting in the village of Râu de Mori, straight up to Retezat Peak.","description":["Marked with a red triangle, the trail climbs from Râu de Mori to Retezat Peak in 7–8 hours, on the massif's southern slope, quieter than the routes from Pietrele Hut.","It's a demanding alternative for those wanting to avoid the crowds in the northern part of the park."],"facts":[{"label":"Starting point","value":"Râu de Mori"},{"label":"Marking","value":"Red triangle"},{"label":"Duration","value":"7–8 hours"}]}},{"id":"traseu-gura-zlata-lacul-bucura","name":"Traseul Cabana Gura Zlata – Lacul Bucura","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"rau-de-mori","hasReviews":false,"images":["images/cabana-gura-zlata.jpg"],"photoCredit":{"author":"Dezidor","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Gura_Zlata.jpg"},"ro":{"tagline":"Ruta de acces dinspre vest, prin Cabana Gura Zlata, spre Lacul Bucura.","description":["Marcat cu triunghi roșu, traseul pornește de la Cabana Gura Zlata (775 m), în partea vestică a masivului, și ajunge la Lacul Bucura în circa 8 ore.","E cel mai lung dintre traseele principale de acces spre Bucura, dar traversează o zonă mai puțin circulată a parcului."],"facts":[{"label":"Punct de plecare","value":"Cabana Gura Zlata (775 m)"},{"label":"Marcaj","value":"Triunghi roșu"},{"label":"Durată","value":"cca. 8 ore"}]},"en":{"name":"Gura Zlata Hut – Lake Bucura trail","tagline":"The western access route, via Gura Zlata Hut, up to Lake Bucura.","description":["Marked with a red triangle, the trail starts at Gura Zlata Hut (775 m), on the western side of the massif, and reaches Lake Bucura in about 8 hours.","It's the longest of the main access routes to Bucura, but crosses a quieter part of the park."],"facts":[{"label":"Starting point","value":"Gura Zlata Hut (775 m)"},{"label":"Marking","value":"Red triangle"},{"label":"Duration","value":"about 8 hours"}]}},{"id":"traseu-lacul-bucura-circuit","name":"Traseul circular al Lacului Bucura","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parcul Național Retezat","townId":"hateg","hasReviews":false,"images":["images/traseu-lacul-bucura.jpg"],"photoCredit":{"author":"Gugalcrom123","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Lake_Bucura_01.jpg"},"ro":{"tagline":"Tur circular de o zi în jurul zonei Lacului Bucura, cel mai mare lac glaciar din România.","description":["Marcat cu punct roșu, circuitul de 11 ore ocolește zona lacurilor din jurul Bucurei, cu priveliști spre principalele vârfuri din jur.","E potrivit celor care înnoptează în zonă (cort sau refugiu) și vor să exploreze bazinul glaciar fără să se limiteze la un singur vârf."],"facts":[{"label":"Zonă","value":"Lacul Bucura"},{"label":"Marcaj","value":"Punct roșu"},{"label":"Durată","value":"cca. 11 ore"}]},"en":{"name":"Lake Bucura loop trail","tagline":"A day-long loop around the Lake Bucura area, Romania's largest glacial lake.","description":["Marked with a red dot, the 11-hour circuit loops around the lake basin near Bucura, with views of the surrounding main peaks.","It suits those camping or staying in a refuge nearby who want to explore the glacial basin rather than just reach a single peak."],"facts":[{"label":"Area","value":"Lake Bucura"},{"label":"Marking","value":"Red dot"},{"label":"Duration","value":"about 11 hours"}]}},{"id":"traseu-baru-varful-tulisa","name":"Traseul Baru – Vârful Tulișa","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Baru Mare","townId":"hateg","hasReviews":false,"images":["images/placeholder.svg"],"ro":{"tagline":"Traseu din partea sudică a Retezatului, dinspre Baru, spre Vârful Tulișa.","description":["Marcat cu cruce galbenă, traseul pornește din Baru și urcă spre Vârful Tulișa în 4–5 ore.","E o rută mai puțin cunoscută decât cele dinspre Cabana Pietrele, potrivită celor care pornesc din zona Hațeg–Baru Mare."],"facts":[{"label":"Punct de plecare","value":"Baru"},{"label":"Marcaj","value":"Cruce galbenă"},{"label":"Durată","value":"4–5 ore"}]},"en":{"name":"Baru – Tulișa Peak trail","tagline":"A trail from the southern side of Retezat, from Baru up to Tulișa Peak.","description":["Marked with a yellow cross, the trail starts in Baru and climbs to Tulișa Peak in 4–5 hours.","It's a lesser-known route than those from Pietrele Hut, suited to those starting from the Hațeg–Baru Mare area."],"facts":[{"label":"Starting point","value":"Baru"},{"label":"Marking","value":"Yellow cross"},{"label":"Duration","value":"4–5 hours"}]}},{"id":"traseu-cheile-butii-cabana-buta","name":"Traseul Cheile Buții – Cabana Buta","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Vâlcan","hasReviews":false,"images":["images/traseu-cheile-butii-cabana-buta.jpg"],"photoCredit":{"author":"Complexul Turistic Cheile Butii","license":"material promoțional al afacerii","source":"https://www.facebook.com/profile.php?id=100057251688574","sourceLabel":"Facebook"},"ro":{"tagline":"Traseu lung prin Munții Vâlcan, de la Cheile Buții la Cabana Buta, peste vârfurile Pleșa și Piule.","description":["Marcat cu bandă galbenă, traseul pornește de la complexul turistic Cheile Buții și trece prin Dâlma Mare, Vârful Pleșa și Vârful Piule înainte de a coborî la Cabana Buta, prin Șaua Scorota.","Cu o durată de 8–9 ore, leagă practic zona Cheilor Buții de rețeaua de trasee din Retezat."],"facts":[{"label":"Punct de plecare","value":"Complex turistic Cheile Buții"},{"label":"Marcaj","value":"Bandă galbenă"},{"label":"Durată","value":"8–9 ore"}]},"en":{"name":"Buta Gorges – Buta Hut trail","tagline":"A long route through the Vâlcan Mountains, from the Buta Gorges to Buta Hut, over Pleșa and Piule peaks.","description":["Marked with a yellow band, the trail starts at the Cheile Buții tourist complex and passes Dâlma Mare, Pleșa Peak and Piule Peak before descending to Buta Hut via Scorota Saddle.","At 8–9 hours, it effectively links the Buții Gorge area to the Retezat trail network."],"facts":[{"label":"Starting point","value":"Cheile Buții tourist complex"},{"label":"Marking","value":"Yellow band"},{"label":"Duration","value":"8–9 hours"}]}},{"id":"traseu-campusel-saua-scorota","name":"Traseul Câmpușel – Șaua Scorota – Cabana Buta","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Vâlcan","townId":"uricani","hasReviews":false,"images":["images/traseu-campusel-saua-scorota.jpg"],"photoCredit":{"author":"Cabana Buta","license":"material promoțional al afacerii","source":"https://www.facebook.com/CabanaButa","sourceLabel":"Facebook"},"ro":{"tagline":"Variantă mai scurtă de acces la Cabana Buta, dinspre Câmpușel, prin Șaua Scorota.","description":["Marcat cu punct galben, traseul urcă din Câmpușel prin Scocul Scorotei și Stâna Scorota până la Șaua Scorota, apoi la Cabana Buta, în 4–5 ore.","E alternativa mai rapidă la traseul dinspre Cheile Buții, pentru cei care pornesc direct din Câmpușel."],"facts":[{"label":"Punct de plecare","value":"Câmpușel"},{"label":"Marcaj","value":"Punct galben"},{"label":"Durată","value":"4–5 ore"}]},"en":{"name":"Câmpușel – Scorota Saddle – Buta Hut trail","tagline":"A shorter access route to Buta Hut, from Câmpușel via Scorota Saddle.","description":["Marked with a yellow dot, the trail climbs from Câmpușel through Scocul Scorotei and Stâna Scorota up to Scorota Saddle, then on to Buta Hut, in 4–5 hours.","It's the faster alternative to the Buta Gorges route, for those starting directly from Câmpușel."],"facts":[{"label":"Starting point","value":"Câmpușel"},{"label":"Marking","value":"Yellow dot"},{"label":"Duration","value":"4–5 hours"}]}},{"id":"traseu-culmea-branu-varful-gugu","name":"Traseul Culmea Branu – Vârful Gugu – Lacul lui Iovan","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Godeanu","townId":"rau-de-mori","hasReviews":false,"images":["images/muntii-godeanu.jpg"],"photoCredit":{"author":"Dezidor","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Godeanu_(3).jpg"},"ro":{"tagline":"Traversare lungă și solicitantă prin Munții Godeanu, cu un tronson parțial nemarcat.","description":["Marcat cu cruce roșie, traseul pornește de la Lacul Gura Apei, urcă pe Culmea Branu spre Vârful Gugu și Vârful Moraru, apoi coboară prin Șaua Mâțului spre Lacul lui Iovan, în 12–13 ore.","Atenție: potrivit Salvamont Hunedoara, tronsonul dintre Vârful Gugu și Vârful Bulzului este parțial nemarcat — recomandat doar cu hartă/GPS și experiență montană."],"facts":[{"label":"Punct de plecare","value":"Lacul Gura Apei"},{"label":"Marcaj","value":"Cruce roșie (parțial nemarcat între Vf. Gugu și Vf. Bulzului)"},{"label":"Durată","value":"12–13 ore"}]},"en":{"name":"Branu Ridge – Gugu Peak – Lake Iovan trail","tagline":"A long, demanding traverse through the Godeanu Mountains, with a partly unmarked section.","description":["Marked with a red cross, the trail starts at Lake Gura Apei, climbs the Branu ridge to Gugu Peak and Moraru Peak, then descends via Mâțului Saddle to Lake Iovan, in 12–13 hours.","Caution: according to Salvamont Hunedoara, the stretch between Gugu Peak and Bulzului Peak is partly unmarked — recommended only with a map/GPS and mountain experience."],"facts":[{"label":"Starting point","value":"Lake Gura Apei"},{"label":"Marking","value":"Red cross (partly unmarked between Gugu Peak and Bulzului Peak)"},{"label":"Duration","value":"12–13 hours"}]}},{"id":"traseu-creasta-valcan-straja-oslea","name":"Traseul de creastă Vâlcan – Straja – Oslea","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Vâlcan","hasReviews":false,"images":["images/creasta-valcan-straja.jpg"],"photoCredit":{"author":"Vlad Fara","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Straja,_Lupeni,_Romania_(Unsplash).jpg"},"ro":{"tagline":"Traversarea de creastă a Munților Vâlcan, pe la Vârful Straja, cel mai lung traseu marcat din zonă.","description":["Marcat cu bandă roșie, traseul urmărește creasta principală a Munților Vâlcan de la Gambrinus (Lupeni), peste vârfurile Drăgoiu, Straja, Mutu, Muncel, Siglăul Mic și Mare, Arcanu și Nedeița, până la Coada Oslei și Câmpușel.","Cu 24–25 de ore de mers, e parcurs de regulă în mai multe etape; trece chiar pe lângă Vârful Straja, cunoscut mai ales pentru stațiunea de schi de pe versantul opus."],"facts":[{"label":"Punct de plecare","value":"Gambrinus (Lupeni)"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"24–25 ore (mai multe etape)"}]},"en":{"name":"Vâlcan – Straja – Oslea ridge trail","tagline":"The Vâlcan Mountains ridge traverse, past Straja Peak — the longest marked trail in the area.","description":["Marked with a red band, the trail follows the main ridge of the Vâlcan Mountains from Gambrinus (Lupeni), over Drăgoiu, Straja, Mutu, Muncel, Siglăul Mic and Mare, Arcanu and Nedeița peaks, to Coada Oslei and Câmpușel.","At 24–25 hours, it's usually covered in several stages; it passes right by Straja Peak, better known for the ski resort on its opposite slope."],"facts":[{"label":"Starting point","value":"Gambrinus (Lupeni)"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"24–25 hours (multiple stages)"}]}},{"id":"traseu-hunedoara-lacul-cincis-cheile-cernei","name":"Traseul Hunedoara – Lacul Cinciș – Cheile Cernei","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Poiana Ruscă","townId":"hunedoara","hasReviews":false,"images":["images/lacul-cincis-panorama.jpg"],"photoCredit":{"author":"magdalena from romania","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Cincis_Lake.jpg"},"ro":{"tagline":"Traseu de mai multe zile prin Munții Poiana Ruscă, pornind chiar din centrul Hunedoarei.","description":["Marcat cu bandă și triunghi albastru, traseul pornește de la Centrul de Informare Turistică din Hunedoara, trece pe la Castelul Corvinilor și Lacul Cinciș, apoi urcă prin Cheile Cernei în Munții Poiana Ruscă.","Cu 18–20 de ore de mers (2–3 zile), e varianta de mijloc ca durată dintre cele trei trasee marcate care pornesc din Hunedoara spre Poiana Ruscă."],"facts":[{"label":"Punct de plecare","value":"Centrul de Informare Turistică Hunedoara"},{"label":"Marcaj","value":"Bandă și triunghi albastru"},{"label":"Durată","value":"18–20 ore (2–3 zile)"}]},"en":{"name":"Hunedoara – Lake Cinciș – Cerna Gorge trail","tagline":"A multi-day route through the Poiana Ruscă Mountains, starting right in downtown Hunedoara.","description":["Marked with a blue band and triangle, the trail starts at the Hunedoara Tourist Information Centre, passes Corvin Castle and Lake Cinciș, then climbs through the Cerna Gorge into the Poiana Ruscă Mountains.","At 18–20 hours (2–3 days), it's the medium-length option among the three marked trails starting in Hunedoara toward Poiana Ruscă."],"facts":[{"label":"Starting point","value":"Hunedoara Tourist Information Centre"},{"label":"Marking","value":"Blue band and triangle"},{"label":"Duration","value":"18–20 hours (2–3 days)"}]}},{"id":"traseu-hunedoara-varful-rusca","name":"Traseul Hunedoara – Lacul Cinciș – Vârful Rusca","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Poiana Ruscă","townId":"hunedoara","hasReviews":false,"images":["images/muntii-poiana-rusca.jpg"],"photoCredit":{"author":"Compactforever","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Poiana_Rusca.jpg"},"ro":{"tagline":"Traseu marcat din Hunedoara spre Vârful Rusca, cel mai înalt punct al masivului cu același nume.","description":["Marcat cu bandă roșie, traseul pornește tot din centrul Hunedoarei, trece pe la Castelul Corvinilor și Lacul Cinciș, apoi urcă spre Vârful Rusca, în 14–16 ore.","E cel mai scurt dintre cele trei trasee marcate spre Poiana Ruscă pornite din Hunedoara."],"facts":[{"label":"Punct de plecare","value":"Centrul de Informare Turistică Hunedoara"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"14–16 ore"}]},"en":{"name":"Hunedoara – Lake Cinciș – Rusca Peak trail","tagline":"A marked trail from Hunedoara up to Rusca Peak, the highest point of the massif bearing its name.","description":["Marked with a red band, the trail also starts in downtown Hunedoara, passes Corvin Castle and Lake Cinciș, then climbs to Rusca Peak in 14–16 hours.","It's the shortest of the three marked trails to Poiana Ruscă starting from Hunedoara."],"facts":[{"label":"Starting point","value":"Hunedoara Tourist Information Centre"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"14–16 hours"}]}},{"id":"traseu-hunedoara-dobra","name":"Traseul Hunedoara – Lacul Cinciș – Dobra","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Poiana Ruscă","townId":"dobra","hasReviews":false,"images":["images/dobra-panorama.jpg"],"photoCredit":{"author":"Krokodilu","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Dobra_Hunedoara.jpg"},"ro":{"tagline":"Cel mai lung traseu marcat din Poiana Ruscă pornit din Hunedoara, cu ieșire la Dobra.","description":["Marcat cu bandă galbenă, traseul pornește din centrul Hunedoarei, trece pe la Castelul Corvinilor și Lacul Cinciș, traversează Munții Poiana Ruscă și coboară la Dobra, în 22–24 ore.","E o traversare completă a masivului, parcursă în mai multe etape."],"facts":[{"label":"Punct de plecare","value":"Centrul de Informare Turistică Hunedoara"},{"label":"Marcaj","value":"Bandă galbenă"},{"label":"Durată","value":"22–24 ore (mai multe etape)"}]},"en":{"name":"Hunedoara – Lake Cinciș – Dobra trail","tagline":"The longest marked trail through Poiana Ruscă starting from Hunedoara, ending at Dobra.","description":["Marked with a yellow band, the trail starts in downtown Hunedoara, passes Corvin Castle and Lake Cinciș, crosses the Poiana Ruscă Mountains and descends to Dobra, in 22–24 hours.","It's a full traverse of the massif, covered in several stages."],"facts":[{"label":"Starting point","value":"Hunedoara Tourist Information Centre"},{"label":"Marking","value":"Yellow band"},{"label":"Duration","value":"22–24 hours (multiple stages)"}]}},{"id":"traseu-ohaba-ponor-cioclovina","name":"Traseul Ohaba Ponor – Peștera Ponorici-Cioclovina","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Țara Hațegului","townId":"pui","hasReviews":false,"images":["images/bosorod-sureanu.jpg"],"photoCredit":{"author":"Țetcu Mircea Rareș","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:RO_HD_Bo%C8%99orod_(4).jpg"},"ro":{"tagline":"Traseu prin Cheile Șura Mare spre sistemul carstic Ponorici-Cioclovina, cea mai lungă peșteră din Munții Șureanu.","description":["Marcat cu bandă roșie, traseul pornește din Ohaba Ponor, trece prin Cheile Șura Mare pe la Peștera Ponorici și Peștera Cioclovina, apoi ajunge la Luncani și Boșorod, în 7–8 ore.","Peștera Cioclovina e cunoscută pentru descoperirea, în 1941, a unui craniu uman fosil datat la 28.000–29.000 de ani."],"facts":[{"label":"Punct de plecare","value":"Ohaba Ponor"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"7–8 ore"}]},"en":{"name":"Ohaba Ponor – Ponorici-Cioclovina Cave trail","tagline":"A trail through the Șura Mare Gorge to the Ponorici-Cioclovina karst system, the longest cave in the Șureanu Mountains.","description":["Marked with a red band, the trail starts in Ohaba Ponor, passes through the Șura Mare Gorge by the Ponorici and Cioclovina caves, then reaches Luncani and Boșorod, in 7–8 hours.","Cioclovina Cave is known for the 1941 discovery of a fossil human skull dated to 28,000–29,000 years ago."],"facts":[{"label":"Starting point","value":"Ohaba Ponor"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"7–8 hours"}]}},{"id":"traseu-baru-varful-lola-porumbelu","name":"Traseul Baru – Vârful Lola – Vârful Porumbelu Mare","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Șureanu","townId":"hateg","hasReviews":false,"images":["images/placeholder.svg"],"ro":{"tagline":"Traseu de creastă în Munții Șureanu, pe Valea Streiului, peste vârfurile Lola și Porumbelu Mare.","description":["Marcat cu bandă roșie, traseul pornește din Baru, urcă pe Valea Streiului și trece pe la Vârful Lola și Vârful Porumbelu Mare, în 7–8 ore.","Oferă acces spre partea sud-vestică a Munților Șureanu, mai puțin circulată decât zona cetăților dacice."],"facts":[{"label":"Punct de plecare","value":"Baru"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"7–8 ore"}]},"en":{"name":"Baru – Lola Peak – Porumbelu Mare Peak trail","tagline":"A ridge trail in the Șureanu Mountains, along the Strei valley, over Lola Peak and Porumbelu Mare Peak.","description":["Marked with a red band, the trail starts in Baru, climbs the Strei valley and passes Lola Peak and Porumbelu Mare Peak, in 7–8 hours.","It gives access to the south-western part of the Șureanu Mountains, quieter than the Dacian fortress area."],"facts":[{"label":"Starting point","value":"Baru"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"7–8 hours"}]}},{"id":"traseu-costesti-sarmizegetusa-regia-varful-godeanu","name":"Traseul Costești – Sarmizegetusa Regia – Vârful Godeanu (Șureanu)","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Șureanu","townId":"orastie","hasReviews":true,"images":["images/sarmizegetusa-zona-sacra.jpg"],"photoCredit":{"author":"Cosmin Stefanescu","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Sarmisegetusa_Regia_-_Zona_sacra_%E2%80%93_Gradistea_Muntelui,_Muntii_Sureanu,_Hunedoara,_Romania_21.JPG"},"ro":{"tagline":"Traseul marcat care leagă satul Costești de capitala regatului dac, Sarmizegetusa Regia, și de Vârful Godeanu.","description":["Marcat cu cruce roșie, traseul urcă din Costești prin Valea Grădiștei și Dealul Grădiștei până la Cetatea Sarmizegetusa Regia, apoi continuă spre Vârful Muncel și Vârful Godeanu, în 10–11 ore.","Atenție: acest Vârf Godeanu se află în Munții Șureanu, lângă cetățile dacice — nu trebuie confundat cu Munții Godeanu, masivul de lângă Retezat."],"facts":[{"label":"Punct de plecare","value":"Costești"},{"label":"Marcaj","value":"Cruce roșie"},{"label":"Durată","value":"10–11 ore"}]},"en":{"name":"Costești – Sarmizegetusa Regia – Godeanu Peak trail (Șureanu)","tagline":"The marked trail linking the village of Costești to the Dacian capital, Sarmizegetusa Regia, and to Godeanu Peak.","description":["Marked with a red cross, the trail climbs from Costești through the Grădiștei valley and hill up to Sarmizegetusa Regia fortress, then continues to Muncel Peak and Godeanu Peak, in 10–11 hours.","Note: this Godeanu Peak is in the Șureanu Mountains, near the Dacian fortresses — not to be confused with the Godeanu Mountains near Retezat."],"facts":[{"label":"Starting point","value":"Costești"},{"label":"Marking","value":"Red cross"},{"label":"Duration","value":"10–11 hours"}]}},{"id":"traseu-costesti-cetatea-blidaru-varful-godeanu","name":"Traseul Costești – Cetatea Blidaru – Vârful Godeanu","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Șureanu","townId":"orastie","hasReviews":true,"images":["images/cetatea-blidaru.jpg"],"photoCredit":{"author":"Oroles","license":"Domeniu public","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Blidaru.JPG"},"ro":{"tagline":"Traseu lung prin zona cetăților dacice, de la Costești, pe la Cetatea Blidaru, până pe Vârful Godeanu.","description":["Marcat cu bandă albastră, traseul pornește din Costești, trece pe la Cetatea Blidaru — a doua ca mărime dintre fortificațiile dacice din zonă, ridicată pe un vârf stâncos — apoi continuă prin Leurdana, Târsa, Poiana Omului, Vârful Rudii și Culmea Meleia până la Vârful Godeanu.","Cu 14–15 ore de mers, e cel mai lung dintre traseele care pornesc din Costești."],"facts":[{"label":"Punct de plecare","value":"Costești"},{"label":"Marcaj","value":"Bandă albastră"},{"label":"Durată","value":"14–15 ore"}]},"en":{"name":"Costești – Blidaru Fortress – Godeanu Peak trail","tagline":"A long trail through the Dacian fortress area, from Costești, past Blidaru Fortress, up to Godeanu Peak.","description":["Marked with a blue band, the trail starts in Costești, passes Blidaru Fortress — the second-largest of the Dacian fortifications in the area, built atop a rocky peak — then continues through Leurdana, Târsa, Poiana Omului, Rudii Peak and the Meleia ridge up to Godeanu Peak.","At 14–15 hours, it's the longest of the trails starting from Costești."],"facts":[{"label":"Starting point","value":"Costești"},{"label":"Marking","value":"Blue band"},{"label":"Duration","value":"14–15 hours"}]}},{"id":"traseu-cetatea-fetele-albe","name":"Traseul Podul Gerosu – Cetatea Fețele Albe","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Șureanu","townId":"orastie","hasReviews":false,"images":["images/cetatea-fetele-albe.jpg"],"photoCredit":{"author":"România de vis","license":"CC BY-SA 3.0 RO","source":"https://commons.wikimedia.org/wiki/File:Ziduri_ale_Cet%C4%83%C5%A3ii_Fe%C5%A3ele-Albe_0298.JPG"},"ro":{"tagline":"Cel mai scurt traseu marcat din zona cetăților dacice, spre ruinele mai puțin vizitate de la Fețele Albe.","description":["Marcat cu triunghi albastru, traseul urcă din zona Podul Gerosu, peste Dealul Muncelului, până la Cetatea Fețele Albe, apoi coboară pe Valea Albă, în doar 3 ore.","Fețele Albe e una dintre fortificațiile dacice mai puțin cunoscute din sistemul din jurul Sarmizegetusei Regia."],"facts":[{"label":"Punct de plecare","value":"Podul Gerosu"},{"label":"Marcaj","value":"Triunghi albastru"},{"label":"Durată","value":"cca. 3 ore"}]},"en":{"name":"Podul Gerosu – Fețele Albe Fortress trail","tagline":"The shortest marked trail in the Dacian fortress area, to the lesser-visited Fețele Albe ruins.","description":["Marked with a blue triangle, the trail climbs from the Podul Gerosu area, over Dealul Muncelului, up to Fețele Albe Fortress, then descends via Valea Albă, in just 3 hours.","Fețele Albe is one of the lesser-known Dacian fortifications in the system around Sarmizegetusa Regia."],"facts":[{"label":"Starting point","value":"Podul Gerosu"},{"label":"Marking","value":"Blue triangle"},{"label":"Duration","value":"about 3 hours"}]}},{"id":"traseu-gradistea-cetatea-piatra-rosie-cioclovina","name":"Traseul Grădiștea de Munte – Cetatea Piatra Roșie – Peștera Cioclovina","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Șureanu","townId":"orastie","hasReviews":false,"images":["images/cetatea-piatra-rosie.jpg"],"photoCredit":{"author":"Korinna","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cetatea_Piatra_Rosie_drum_pavat.jpg"},"ro":{"tagline":"Traseu care leagă Sarmizegetusa Regia de Cetatea Piatra Roșie și de Peștera Cioclovina.","description":["Marcat cu triunghi roșu, traseul pornește din Grădiștea de Munte, trece prin Prihodiște și Poiana Omului până la Cetatea Piatra Roșie, apoi coboară pe Valea Roșia spre Cioclovina, în 7–8 ore.","Piatra Roșie e a treia mare fortificație dacică din zonă, alături de Sarmizegetusa Regia și Blidaru."],"facts":[{"label":"Punct de plecare","value":"Grădiștea de Munte"},{"label":"Marcaj","value":"Triunghi roșu"},{"label":"Durată","value":"7–8 ore"}]},"en":{"name":"Grădiștea de Munte – Piatra Roșie Fortress – Cioclovina Cave trail","tagline":"A trail linking Sarmizegetusa Regia to Piatra Roșie Fortress and to Cioclovina Cave.","description":["Marked with a red triangle, the trail starts in Grădiștea de Munte, passes through Prihodiște and Poiana Omului to Piatra Roșie Fortress, then descends via Valea Roșia toward Cioclovina, in 7–8 hours.","Piatra Roșie is the third major Dacian fortification in the area, alongside Sarmizegetusa Regia and Blidaru."],"facts":[{"label":"Starting point","value":"Grădiștea de Munte"},{"label":"Marking","value":"Red triangle"},{"label":"Duration","value":"7–8 hours"}]}},{"id":"traseu-telescaun-parangul-mare","name":"Traseul Telescaun Parâng – Vârful Parângul Mare","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parâng","hasReviews":true,"images":["images/varful-parangul-mare.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Varful_Parangul_Mare_(2519m)_-_panoramio.jpg"},"ro":{"tagline":"Cel mai direct traseu spre Vârful Parângul Mare (2.519 m), al doilea cel mai înalt vârf din Carpații Meridionali.","description":["Marcat cu bandă roșie, traseul pornește de la capătul telescaunului din stațiunea Parâng (1.685 m) și urcă spre Vârful Parângul Mare în 4–5 ore.","Telescaunul (accesibil în circa 1 oră și jumătate de la baza pârtiei) scurtează considerabil apropierea, fiind cea mai populară cale de a ajunge pe creasta Parângului dinspre Petroșani."],"facts":[{"label":"Punct de plecare","value":"Capătul telescaunului, stațiunea Parâng (1.685 m)"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"4–5 ore"}]},"en":{"name":"Parâng chairlift – Parângul Mare Peak trail","tagline":"The most direct trail to Parângul Mare Peak (2,519 m), the second-highest peak in the Southern Carpathians.","description":["Marked with a red band, the trail starts at the chairlift landing in the Parâng resort (1,685 m) and climbs to Parângul Mare Peak in 4–5 hours.","The chairlift (about 1.5 hours from the base) considerably shortens the approach, making this the most popular way to reach the Parâng ridge from Petroșani."],"facts":[{"label":"Starting point","value":"Chairlift landing, Parâng resort (1,685 m)"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"4–5 hours"}]}},{"id":"traseu-telescaun-varful-carja","name":"Traseul Telescaun Parâng – Vârful Cârja","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parâng","hasReviews":false,"images":["images/varful-carja.jpg"],"photoCredit":{"author":"Thalpha","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Parang_mountain_Carja_peak_1.jpg"},"ro":{"tagline":"Traseu mai scurt decât cel spre Parângul Mare, spre Vârful Cârja (2.407 m).","description":["Marcat cu bandă roșie, traseul pornește tot de la capătul telescaunului din stațiunea Parâng (1.685 m) și urcă spre Vârful Cârja în circa 2 ore și jumătate.","E o variantă mai accesibilă pentru cei care vor o ieșire pe creastă fără să meargă până pe Parângul Mare."],"facts":[{"label":"Punct de plecare","value":"Capătul telescaunului, stațiunea Parâng (1.685 m)"},{"label":"Marcaj","value":"Bandă roșie"},{"label":"Durată","value":"cca. 2 ore 30 min"}]},"en":{"name":"Parâng chairlift – Cârja Peak trail","tagline":"A shorter trail than the one to Parângul Mare, up to Cârja Peak (2,407 m).","description":["Marked with a red band, the trail also starts at the chairlift landing in the Parâng resort (1,685 m) and climbs to Cârja Peak in about 2.5 hours.","It's a more accessible option for those wanting a ridge outing without going all the way to Parângul Mare."],"facts":[{"label":"Starting point","value":"Chairlift landing, Parâng resort (1,685 m)"},{"label":"Marking","value":"Red band"},{"label":"Duration","value":"about 2h30"}]}},{"id":"traseu-lacul-calcescu","name":"Traseul spre Lacul Câlcescu (Parâng)","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parâng","hasReviews":false,"images":["images/lacul-calcescu.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_C%C3%A2lcescu_-_panoramio.jpg"},"ro":{"tagline":"Traseu spre Lacul Câlcescu, cel mai mare lac glaciar din Munții Parâng.","description":["Marcat cu bandă și cruce roșie, traseul pornește de la capătul telescaunului din stațiunea Parâng și ajunge la Lacul Câlcescu în 6–7 ore.","E cel mai lung dintre traseele obișnuite dinspre stațiunea Parâng, potrivit celor care vor să vadă lacul fără să continue spre Obârșia Lotrului."],"facts":[{"label":"Punct de plecare","value":"Capătul telescaunului, stațiunea Parâng"},{"label":"Marcaj","value":"Bandă și cruce roșie"},{"label":"Durată","value":"6–7 ore"}]},"en":{"name":"Trail to Lake Câlcescu (Parâng)","tagline":"A trail to Lake Câlcescu, the largest glacial lake in the Parâng Mountains.","description":["Marked with a red band and cross, the trail starts at the chairlift landing in the Parâng resort and reaches Lake Câlcescu in 6–7 hours.","It's the longest of the usual routes from the Parâng resort, suited to those who want to see the lake without continuing on to Obârșia Lotrului."],"facts":[{"label":"Starting point","value":"Chairlift landing, Parâng resort"},{"label":"Marking","value":"Red band and cross"},{"label":"Duration","value":"6–7 hours"}]}},{"id":"traseu-lacurile-verzi-parang","name":"Traseul spre Lacurile Verzi (Parâng)","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parâng","hasReviews":false,"images":["images/lacul-verde-parang.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_Verde_-_panoramio.jpg"},"ro":{"tagline":"Traseu dinspre Cabana Groapa Seacă spre Lacurile Verzi, în versantul hunedorean al Parângului.","description":["Marcat cu cruce galbenă, traseul pleacă de la Cabana Groapa Seacă și ajunge la Lacurile Verzi în 3–4 ore.","Cabana Groapa Seacă se atinge, la rândul ei, printr-un traseu marcat cu bandă și punct roșu de la Șaua Gruiul, punct de legătură cu traseele dinspre telescaun."],"facts":[{"label":"Punct de plecare","value":"Cabana Groapa Seacă"},{"label":"Marcaj","value":"Cruce galbenă"},{"label":"Durată","value":"3–4 ore"}]},"en":{"name":"Trail to the Green Lakes (Parâng)","tagline":"A trail from Groapa Seacă Hut to the Green Lakes, on the Hunedoara side of the Parâng massif.","description":["Marked with a yellow cross, the trail leaves from Groapa Seacă Hut and reaches the Green Lakes in 3–4 hours.","Groapa Seacă Hut is itself reached via a trail marked with a red band and dot from Gruiul Saddle, a junction with the routes from the chairlift."],"facts":[{"label":"Starting point","value":"Groapa Seacă Hut"},{"label":"Marking","value":"Yellow cross"},{"label":"Duration","value":"3–4 hours"}]}},{"id":"traseu-refugiul-agatat-lacul-rosiile","name":"Traseul spre Lacul Roșiile și Refugiul Agățat (Parâng)","category":{"ro":"Drumeție montană","en":"Mountain hiking"},"area":"Parâng","hasReviews":false,"images":["images/lacul-rosiile.jpg"],"photoCredit":{"author":"Cioboata Andrei","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Lacul_Rosiile_-_panoramio_(1).jpg"},"ro":{"tagline":"Traseu scurt de la Șaua Gruiul spre Lacul Roșiile și Refugiul Agățat.","description":["Marcat cu punct roșu, traseul leagă Șaua Gruiul de Lacul Roșiile și Refugiul Agățat în doar 1–1,5 ore.","E una dintre cele mai scurte variante de ieșire pe creasta Parângului dinspre zona telescaunului."],"facts":[{"label":"Punct de plecare","value":"Șaua Gruiul"},{"label":"Marcaj","value":"Punct roșu"},{"label":"Durată","value":"1–1,5 ore"}]},"en":{"name":"Trail to Lake Roșiile and the Agățat Refuge (Parâng)","tagline":"A short trail from Gruiul Saddle to Lake Roșiile and the Agățat Refuge.","description":["Marked with a red dot, the trail links Gruiul Saddle to Lake Roșiile and the Agățat Refuge in just 1–1.5 hours.","It's one of the shortest ridge outings from the chairlift area."],"facts":[{"label":"Starting point","value":"Gruiul Saddle"},{"label":"Marking","value":"Red dot"},{"label":"Duration","value":"1–1.5 hours"}]}},{"id":"statiunea-geoagiu-bai","name":"Stațiunea Geoagiu-Băi","category":{"ro":"Stațiune balneară","en":"Spa resort"},"area":"Geoagiu","townId":"geoagiu","coords":[45.9353,23.1633],"hasReviews":true,"season":"tot-anul","images":["images/geoagiu-bai-cascada.jpg"],"photoCredit":{"author":"mihai moise","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Cascada_Geoagiu_-_panoramio_(1).jpg"},"ro":{"tagline":"Stațiune balneoclimaterică permanentă, cu ape termale, ștrand cu bazin olimpic și terme romane vechi de aproape două milenii.","description":["Geoagiu-Băi este o stațiune balneoclimaterică permanentă, parte a orașului Geoagiu, situată la circa 18 km nord de Orăștie, la 350 m altitudine, într-o zonă deluroasă de la poalele Munților Metaliferi. Apele mezotermale și termale (29–32 °C) sunt alcaline, ușor sulfuroase, bicarbonatate și magneziene și sunt folosite mai ales pentru afecțiuni ale aparatului locomotor, ginecologice, metabolice și dermatologice.","Ștrandul cu apă termală are trei bazine, printre care un bazin olimpic, cu apă de 32–33 °C. În stațiune se pot vizita și termele romane Germisara, o porțiune bine păstrată de drum roman și cascada, iar în apropiere, la Geoagiu, rotonda romanică din secolele XI–XII. În nordul stațiunii se află rezervația naturală „Apele mezotermale Geoagiu-Băi” (8 ha), care protejează pădurea din jurul izvoarelor.","În 2008, Geoagiu-Băi a fost clasificată stațiune turistică de interes național, iar în 2010 a fost desemnată Destinație Europeană de Excelență (EDEN) a României, la tema turism acvatic."],"facts":[{"label":"Altitudine","value":"350 m"},{"label":"Distanțe","value":"~18 km de Orăștie, ~46 km de Deva"},{"label":"Ape","value":"mezotermale și termale, 29–32 °C"},{"label":"Ștrand","value":"3 bazine cu apă termală (32–33 °C), inclusiv bazin olimpic"},{"label":"Distincții","value":"stațiune de interes național (2008), EDEN 2010"}]},"en":{"name":"Geoagiu-Băi spa resort","tagline":"A year-round spa resort with thermal waters, an outdoor pool complex with an Olympic pool, and Roman baths almost two millennia old.","description":["Geoagiu-Băi is a year-round spa and climatic resort, part of the town of Geoagiu, about 18 km north of Orăștie, at 350 m altitude, in hilly country at the foot of the Metaliferi Mountains. Its mesothermal and thermal waters (29–32 °C) are alkaline, slightly sulphurous, bicarbonated and magnesian, used mainly for locomotor, gynaecological, metabolic and skin conditions.","The thermal outdoor pool complex has three pools, including an Olympic-size one, with water at 32–33 °C. Also in the resort are the Germisara Roman baths, a well-preserved stretch of Roman road and a waterfall, while nearby Geoagiu has an 11th–12th century Romanesque rotunda. The north of the resort holds the \"Geoagiu-Băi mesothermal waters\" nature reserve (8 ha), which protects the forest around the springs.","In 2008 Geoagiu-Băi was classified as a tourist resort of national interest, and in 2010 it was named Romania's European Destination of Excellence (EDEN) for aquatic tourism."],"facts":[{"label":"Altitude","value":"350 m"},{"label":"Distances","value":"~18 km from Orăștie, ~46 km from Deva"},{"label":"Waters","value":"mesothermal and thermal, 29–32 °C"},{"label":"Outdoor pools","value":"3 thermal-water pools (32–33 °C), including an Olympic pool"},{"label":"Awards","value":"resort of national interest (2008), EDEN 2010"}]}},{"id":"baile-vata-de-jos","name":"Băile Vața de Jos (Vața Băi)","category":{"ro":"Stațiune balneară","en":"Spa resort"},"area":"Vața de Jos","townId":"vata-de-jos","coords":[46.1833,22.6],"hasReviews":true,"season":"tot-anul","images":["images/baile-vata-de-jos.jpg"],"photoCredit":{"author":"Complexul Vața Băi","license":"material promoțional al afacerii","source":"https://www.facebook.com/VataBai","sourceLabel":"Facebook"},"ro":{"tagline":"Stațiune cu ape termale de 36–38 °C în valea Crișului Alb, redeschisă după mai bine de un deceniu de abandon.","description":["Stațiunea se află în comuna Vața de Jos, în valea Crișului Alb, la poalele Munților Zarandului, la circa 19 km de Brad. Apele termale, folosite într-o stațiune funcțională încă de la mijlocul secolului al XIX-lea, ies la suprafață la circa 36–38 °C și conțin calciu, sulf, sodiu și magneziu.","În anii 1970, complexul a fost extins ca bază de tratament pentru afecțiuni ale aparatului locomotor și ale sistemului nervos periferic. Închis și pus în conservare în 2010, a fost cumpărat de investitori privați și redeschis după mai bine de un deceniu, cu bazine cu apă termală, cazare și centru de tratament.","În aceeași comună, în satul Vața de Sus, s-a născut în 1910 părintele Arsenie Boca, înmormântat la Mănăstirea Prislop."],"facts":[{"label":"Distanțe","value":"~19 km de Brad, ~58 km de Deva"},{"label":"Apă termală","value":"36–38 °C, cu calciu, sulf, sodiu și magneziu"},{"label":"Istoric","value":"stațiune funcțională de la mijlocul secolului al XIX-lea"},{"label":"Stare","value":"închisă în 2010, redeschisă de investitori privați"}]},"en":{"name":"Vața de Jos thermal baths (Vața Băi)","tagline":"A thermal spa with 36–38 °C waters in the Crișul Alb valley, reopened after more than a decade of neglect.","description":["The resort lies in Vața de Jos commune, in the Crișul Alb valley at the foot of the Zarand Mountains, about 19 km from Brad. Its thermal waters, used by a working spa since the mid-19th century, emerge at about 36–38 °C and contain calcium, sulphur, sodium and magnesium.","In the 1970s the complex was expanded into a treatment centre for locomotor and peripheral nervous system conditions. Closed and mothballed in 2010, it was bought by private investors and reopened more than a decade later, with thermal-water pools, accommodation and a treatment centre.","In the same commune, in the village of Vața de Sus, Father Arsenie Boca was born in 1910; he is buried at Prislop Monastery."],"facts":[{"label":"Distances","value":"~19 km from Brad, ~58 km from Deva"},{"label":"Thermal water","value":"36–38 °C, with calcium, sulphur, sodium and magnesium"},{"label":"History","value":"a working spa since the mid-19th century"},{"label":"Status","value":"closed in 2010, reopened by private investors"}]}}];
